import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Pb {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());
        String text = reader.readLine();

        List<String> insideWords = new ArrayList<>();
        StringBuilder currentWord = new StringBuilder();
        int outsideLength = 0;
        int maxOutsideLength = 0;
        boolean insideParentheses = false;

        int i = 0;
        while (i < n) {
            char ch = text.charAt(i);

            if (ch == '(') {
                if (outsideLength >= maxOutsideLength) {
                    maxOutsideLength = outsideLength;
                }
                outsideLength = 0;
                insideParentheses = true;
            } else if (ch == ')') {
                insideParentheses = false;
                if (currentWord.length() != 0) {
                    insideWords.add(currentWord.toString());
                    currentWord.setLength(0);
                }
            } else if (insideParentheses) {
                if (ch != '_') {
                    currentWord.append(ch);
                } else if (currentWord.length() != 0) {
                    insideWords.add(currentWord.toString());
                    currentWord.setLength(0);
                }
            } else if (ch != '_') {
                outsideLength++;
                if (i == n - 1 && outsideLength >= maxOutsideLength) {
                    maxOutsideLength = outsideLength;
                }
            } else {
                if (outsideLength >= maxOutsideLength) {
                    maxOutsideLength = outsideLength;
                }
                outsideLength = 0;
            }

            i++;
        }

        System.out.println(maxOutsideLength + " " + insideWords.size());
    }
}
